target.css:
:root {
  --bib-bg: #fdf3e3;
  --bib-border: #b85c1a;
  --bib-header-bg: #b85c1a;
  --bib-header-text: #fdf3e3;
  --bib-number-color: #b85c1a;
  --bib-number-border: #b85c1a;
  --bib-name-color: #3a2010;
  --bib-muted: #7a4e2d;
  --bib-footer-bg: #f5e0c0;
  --bib-footer-text: #7a4e2d;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.bib {
  background-color: var(--bib-bg);
  border: 3px solid var(--bib-border);
  border-radius: 8px;
  width: 340px;
  overflow: hidden;
}

.bib-header {
  background-color: var(--bib-header-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 16px;
  gap: 2px;
}

.bib-event {
  color: var(--bib-header-text);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 3px;
}

.bib-subtitle {
  color: var(--bib-header-text);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 1px;
  opacity: 0.88;
}

.bib-body {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 18px 24px;
}

.bib-number {
  font-size: 64px;
  font-weight: 900;
  color: var(--bib-number-color);
  border: 3px solid var(--bib-number-border);
  border-radius: 6px;
  width: 90px;
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.bib-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bib-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--bib-name-color);
  margin: 0;
}

.bib-category {
  font-size: 13px;
  font-weight: 500;
  color: var(--bib-muted);
  margin: 0;
}

.bib-year {
  font-size: 11px;
  font-weight: 400;
  color: var(--bib-muted);
  margin: 0;
  font-style: italic;
}

.bib-footer {
  background-color: var(--bib-footer-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 8px 16px;
  border-top: 2px dashed var(--bib-border);
}

.bib-cheese {
  font-size: 16px;
}

.bib-rule {
  font-size: 11px;
  font-weight: 600;
  color: var(--bib-footer-text);
  letter-spacing: 0.5px;
}

